class Diagnostic(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    code: constr(pattern=r'^[EW][0-9]{3}$') = Field(
        ...,
        description='Diagnostic code: E0xx block checks, E1xx model checks, E3xx bindings, E9xx internal and solver, W2xx warnings.',
    )
    severity: DiagnosticSeverity = Field(..., title='DiagnosticSeverity')
    message: str
    hint: str | None = Field(
        None, description='What to do about it, when there is something to say.'
    )
    path: (
        constr(
            pattern=r'^([A-Za-z_][A-Za-z0-9_]*/)*[A-Za-z_][A-Za-z0-9_]*$|^(joint|link|frame|visual):[A-Za-z0-9_.-]+$'
        )
        | None
    ) = Field(
        None,
        description='Instance path (plan 3.1), a scene target for binding diagnostics, or null for a model-wide diagnostic.',
    )
    block: (
        constr(
            pattern=r'^(stdlib:[A-Za-z0-9_]+(/[A-Za-z0-9_]+)*|project:[A-Za-z_][A-Za-z0-9_]*|inline:[A-Za-z0-9_.-]+)$'
        )
        | None
    ) = Field(
        None,
        description='Block reference, when the diagnostic points at a library or project block.',
    )
    scope: str | None = Field(
        None,
        description='Source scope, e.g. @equations, when the diagnostic is source-level.',
    )
    source: DiagnosticSource | None = Field(
        None, description='The source location, when the diagnostic is source-level.'
    )
    node: str | None = Field(
        None, description='Editor node id, for canvas highlighting.'
    )
    connection: str | None = Field(
        None, description='Editor connection id, for canvas highlighting.'
    )
    related: list[RelatedDiagnostic] | None = None
    field_comment: str | None = Field(None, alias='$comment')


